def _resolve_json_payload_to_dict(payload: Any) -> dict:
    """
    Resolve a Databricks ``json`` payload into a plain, independent ``dict``.

    The payload may already be a mapping, ``None``, or a string produced by Jinja
    templating. A templated string is first parsed as JSON; if that fails it is
    parsed as a Python literal (the ``repr`` of a dict that Jinja emits when
    rendering a value pulled from XCom). The returned dict is a deep copy so that
    callers may freely mutate it without touching the operator's template fields.
    """
    if isinstance(payload, str):
        try:
            payload = json.loads(payload)
        except (ValueError, TypeError):
            try:
                payload = ast.literal_eval(payload)
            except (ValueError, SyntaxError):
                raise AirflowException("Databricks json payload string must be valid JSON")
    if payload is None:
        return {}
    if not isinstance(payload, dict):
        raise AirflowException("Databricks json payload must resolve to a mapping")
    return copy.deepcopy(payload)


